def distribute_into_n_buckets_by_value_range(nums, n):
    if not nums:
        return [[] for _ in range(n)]
    lo = min(nums)
    hi = max(nums)
    span = (hi - lo) / n if hi > lo else 1
    result = [[] for _ in range(n)]
    for value in nums:
        pos = int((value - lo) / span)
        if pos >= n:
            pos = n - 1
        result[pos].append(value)
    return [sorted(bucket) for bucket in result]

