def flatten_nested_dict(nested):
    result = {}
    stack = [('', nested)]
    while stack:
        prefix, d = stack.pop()
        for k, v in d.items():
            key = f'{prefix}.{k}' if prefix else str(k)
            if isinstance(v, dict):
                stack.append((key, v))
            else:
                result[key] = v
    return result

